// Build the batch payload for the JobSpy sidecar from Airtable Search Queries rows

const items = $input.all();
const queries = [];
const queryMeta = []; // Track record IDs for updating Last Run later

for (const item of items) {
  const row = item.json.fields || item.json;
  const recordId = item.json.id || null;

  // Skip rows without a query string
  const queryString = row['Query String'];
  if (!queryString) continue;

  // Parse JobSpy Sites (comma-separated string to array)
  const sitesRaw = row['JobSpy Sites'] || 'indeed,linkedin';
  const sites = sitesRaw.split(',').map(s => s.trim().toLowerCase()).filter(s => s.length > 0);

  // Title keywords per query
  const titleKeywords = row['Title Keywords'] || '';

  queries.push({
    search_term: queryString,
    location: row['Location'] || '',
    sites: sites,
    country_indeed: row['Country Filter'] || 'Canada',
    hours_old: row['Hours Old'] || 72,
    results_wanted: row['Results Wanted'] || 50,
    source_tag: row['Source Tag'] || '',
    description_format: 'markdown',
    linkedin_fetch_description: true,
    title_keywords: titleKeywords
  });

  queryMeta.push({
    recordId: recordId,
    queryName: row['Query'] || row['Query Name'] || queryString
  });
}

if (queries.length === 0) {
  return [{ json: { _empty: true, _message: 'No enabled JobSpy Search Queries found' } }];
}

return [{ json: { queries, queryMeta, queryCount: queries.length } }];

// Parse JobSpy batch response into individual job items
// Apply per-query title keyword filter, geography filter, and generate FNV-1a Job IDs

const response = $input.first().json;

if (!response.success) {
  return [{ json: { _empty: true, _error: response.error || 'JobSpy batch call failed' } }];
}

// Get the original queries with their per-query title keywords
const batchPayload = $('Build Batch Payload').first().json;
const originalQueries = batchPayload.queries || [];

// Geography filter — same pattern as Workflows 1a/1b/1c
// TODO: Read from Profile.Target Geography in v1.1
// Dynamic geography from Profile table (same pattern as Workflows 1a/1b/1c)
const profileData = $('Get Profile').first().json;
const geoField = profileData['Target Geography'];
const userGeographies = Array.isArray(geoField) ? geoField : ['Remote Global'];

const GEO_CONFIG = {
  'Canada': {
    substrings: ['canada', 'toronto', 'vancouver', 'montreal', 'ottawa', 'calgary', 'mississauga', 'edmonton', 'waterloo', 'quebec', 'ontario', 'british columbia', 'alberta']
  },
  'USA': {
    substrings: ['united states', 'usa', 'new york', 'san francisco', 'los angeles', 'seattle', 'chicago', 'austin', 'boston', 'denver']
  },
  'Remote Global': {
    substrings: ['remote', 'worldwide', 'global', 'anywhere']
  },
  'Remote North America': {
    substrings: ['remote north america', 'remote - north america', 'remote na', 'remote us/canada', 'remote us and canada']
  }
};

const allowedSubstrings = new Set();
for (const geo of userGeographies) {
  const cfg = GEO_CONFIG[geo];
  if (cfg) {
    cfg.substrings.forEach(s => allowedSubstrings.add(s));
  }
}

const matchesGeography = (locationStr, isRemote) => {
  if (!locationStr || locationStr === 'Not specified') {
    if (isRemote) return true;
    return true; // Let unspecified through, Evaluator will filter
  }
  const loc = locationStr.toLowerCase();
  for (const sub of allowedSubstrings) {
    if (loc.includes(sub)) return true;
  }
  return false;
};

// FNV-1a hash — same as all other scanner workflows
const fnv1aHash = (str) => {
  let hash = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
};

const siteToSource = {
  'indeed': 'Indeed',
  'linkedin': 'LinkedIn',
  'zip_recruiter': 'ZipRecruiter',
  'glassdoor': 'Glassdoor',
  'google': 'Google Jobs'
};

const allJobs = [];
const seen = new Set();
let rawTotal = 0;
let geoFiltered = 0;
let titleFiltered = 0;

const queryResults = response.query_results || [];

for (let qi = 0; qi < queryResults.length; qi++) {
  const queryResult = queryResults[qi];
  const sourceTag = queryResult.source_tag || '';
  const searchTerm = queryResult.search_term || '';

  // Get per-query title keywords from the original query config
  const origQuery = originalQueries[qi] || {};
  const titleKeywordsRaw = origQuery.title_keywords || '';
  const titleKeywords = titleKeywordsRaw
    .split(',')
    .map(k => k.trim().toLowerCase())
    .filter(k => k.length > 0);

  for (const job of (queryResult.jobs || [])) {
    rawTotal++;
    if (!job.title || !job.job_url) continue;

    // Per-query title keyword filter
    if (titleKeywords.length > 0) {
      const t = job.title.toLowerCase();
      if (!titleKeywords.some(kw => t.includes(kw))) {
        titleFiltered++;
        continue;
      }
    }

    const location = job.location || 'Not specified';
    if (!matchesGeography(location, job.is_remote)) {
      geoFiltered++;
      continue;
    }

    const applyLink = job.job_url_direct || job.job_url;
    const company = job.company || 'Unknown';

    const hashInput = `${job.title}|${company}|${applyLink}`;
    const jobId = fnv1aHash(hashInput) + '-spy';

    if (seen.has(jobId)) continue;
    seen.add(jobId);

    const source = siteToSource[job.site] || job.site || 'Indeed';

    let salaryInfo = '';
    if (job.salary_min && job.salary_max) {
      const currency = job.salary_currency || 'USD';
      const interval = job.salary_interval || 'yearly';
      salaryInfo = `${currency} ${Math.round(job.salary_min).toLocaleString()} - ${Math.round(job.salary_max).toLocaleString()} (${interval})`;
    } else if (job.salary_min) {
      salaryInfo = `${job.salary_currency || 'USD'} ${Math.round(job.salary_min).toLocaleString()}+`;
    }

    let description = job.description || '';
    if (description.length > 50000) {
      description = description.substring(0, 50000) + '\n\n[Description truncated]';
    }

    allJobs.push({
      json: {
        jobId,
        jobTitle: job.title,
        company,
        location,
        applyLink,
        jobDescription: description,
        source,
        sourceQuery: searchTerm,
        sourceTag,
        discoveryDate: new Date().toISOString().split('T')[0],
        salaryInfo,
        isRemote: job.is_remote || false
      }
    });
  }
}

if (allJobs.length === 0) {
  return [{ json: { _empty: true, _message: `JobSpy: ${rawTotal} raw, ${titleFiltered} title-filtered, ${geoFiltered} geo-filtered, 0 survived` } }];
}

return allJobs;

// Deduplicate parsed jobs against existing Pipeline records
// Same logic as Workflows 1a, 1b, 1c

const parsedJobs = $('Parse & Filter Jobs').all().filter(item => !item.json._empty);
const existingRecords = $('Get Existing Job IDs').all();

const existingIds = new Set();
for (const record of existingRecords) {
  let jobId = null;
  if (record.json.fields && record.json.fields['Job ID']) {
    jobId = record.json.fields['Job ID'];
  } else if (record.json['Job ID']) {
    jobId = record.json['Job ID'];
  }
  if (jobId) existingIds.add(jobId);
}

const netNew = parsedJobs.filter(item => !existingIds.has(item.json.jobId));

// Safety brake: cap at 100 new records per run
if (netNew.length > 100) {
  throw new Error(`Safety brake: ${netNew.length} net-new jobs exceeds 100 limit. Review query config or increase cap.`);
}

if (netNew.length === 0) {
  return [{ json: { _empty: true, _message: `${parsedJobs.length} jobs found, all already in Pipeline` } }];
}

return netNew;

// Unwrap NocoDB Data API v3 response
const response = $input.first().json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { _empty: true, _message: 'No Profile found' } }];
}

return records.map(record => ({
  json: { ...record.fields, id: record.id }
}));

// Unwrap NocoDB Data API v3 response
const response = $input.first().json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { _empty: true, _message: 'No enabled Search Queries found' } }];
}

return records.map(record => ({
  json: { ...record.fields, id: record.id }
}));

// Unwrap NocoDB Data API v3 — field-projected response (only 'Job ID' field)
const response = $input.first().json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { _empty: true, _message: 'No existing Job IDs found' } }];
}

return records.map(record => ({
  json: {
    'Job ID': record.fields['Job ID'],
    id: record.id
  }
}));
